-- Local-only fixture for wrangler D1 (--local).
-- Do not apply with --remote. Re-run replaces workspace "Northwind Labs".
-- Apply via: bun run seed:local
--
-- Stable ids live in 00000000-0000-4000-a000-* so the file is deterministic.

PRAGMA foreign_keys = OFF;

DELETE FROM tag_documents WHERE workspace_id IN (
  SELECT id FROM workspaces WHERE id = '00000000-0000-4000-a000-000000000001' OR name = 'Northwind Labs'
);
DELETE FROM tag_persons WHERE workspace_id IN (
  SELECT id FROM workspaces WHERE id = '00000000-0000-4000-a000-000000000001' OR name = 'Northwind Labs'
);
DELETE FROM document_persons WHERE workspace_id IN (
  SELECT id FROM workspaces WHERE id = '00000000-0000-4000-a000-000000000001' OR name = 'Northwind Labs'
);
DELETE FROM document_versions WHERE document_id IN (
  SELECT id FROM documents WHERE workspace_id IN (
    SELECT id FROM workspaces WHERE id = '00000000-0000-4000-a000-000000000001' OR name = 'Northwind Labs'
  )
);
DELETE FROM documents WHERE workspace_id IN (
  SELECT id FROM workspaces WHERE id = '00000000-0000-4000-a000-000000000001' OR name = 'Northwind Labs'
);
DELETE FROM tags WHERE workspace_id IN (
  SELECT id FROM workspaces WHERE id = '00000000-0000-4000-a000-000000000001' OR name = 'Northwind Labs'
);
DELETE FROM custom_field_values WHERE workspace_id IN (
  SELECT id FROM workspaces WHERE id = '00000000-0000-4000-a000-000000000001' OR name = 'Northwind Labs'
);
DELETE FROM custom_field_definitions WHERE workspace_id IN (
  SELECT id FROM workspaces WHERE id = '00000000-0000-4000-a000-000000000001' OR name = 'Northwind Labs'
);
DELETE FROM person_table_views WHERE workspace_id IN (
  SELECT id FROM workspaces WHERE id = '00000000-0000-4000-a000-000000000001' OR name = 'Northwind Labs'
);
UPDATE persons SET dotted_manager_id = NULL WHERE workspace_id IN (
  SELECT id FROM workspaces WHERE id = '00000000-0000-4000-a000-000000000001' OR name = 'Northwind Labs'
);
DELETE FROM persons WHERE workspace_id IN (
  SELECT id FROM workspaces WHERE id = '00000000-0000-4000-a000-000000000001' OR name = 'Northwind Labs'
);
DELETE FROM workspaces
WHERE id = '00000000-0000-4000-a000-000000000001'
   OR name = 'Northwind Labs';

PRAGMA foreign_keys = ON;

